//! Independent receipt/source review and source-index classification; no observer/classifier imports.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-pack-locality176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/review.json")).exists());let mut pins=BTreeMap::new();let mut commands=0;
for(dir,plan)in[("native","native-plan.json"),("link-runs","link-plan.json"),("runs","capture-plan.json")]{let p=read(format!("{R}/{plan}"));let mut normalized=p.clone();normalized.as_object_mut().unwrap().entry("environment").or_insert(json!({}));for s in normalized["steps"].as_array_mut().unwrap(){s.as_object_mut().unwrap().entry("environment").or_insert(json!({}));s.as_object_mut().unwrap().entry("required_tests").or_insert(json!([]));s.as_object_mut().unwrap().entry("unfiltered").or_insert(json!(false));}assert_eq!(read(format!("{R}/{dir}/protocol.json")),normalized);let source=read(p["source_pins"].as_str().unwrap());assert_eq!(source,read(format!("{R}/{dir}/source-pins.json")));for(p,h)in source.as_object().unwrap(){if let Some(old)=pins.insert(p.clone(),h.as_str().unwrap().to_string()){assert_eq!(old,h.as_str().unwrap());}}
assert_eq!(read(format!("{R}/{dir}/attempt-0.json"))["resume"],false);assert_eq!(fs::read_dir(format!("{R}/{dir}")).unwrap().filter(|e|e.as_ref().unwrap().file_name().to_string_lossy().starts_with("attempt-")).count(),1);let mut names=Vec::new();for s in p["steps"].as_array().unwrap(){let name=s["name"].as_str().unwrap();names.push(name.to_string());let c=read(format!("{R}/{dir}/{name}/command.json"));let e=read(format!("{R}/{dir}/{name}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(format!("{R}/{dir}/{name}/{stream}.log")),e[format!("{stream}_sha256")]);}let argv=c["argv"].as_array().unwrap();let wanted=s["argv"].as_array().unwrap();assert!(argv.ends_with(wanted));assert_eq!(argv.len(),wanted.len()+4);assert_eq!(argv[..3],[json!("timeout"),json!("-k"),json!("5s")]);assert_eq!(argv[3],format!("{}s",s["timeout_seconds"].as_u64().unwrap()));let mut env=s["environment"].clone();if env.is_null(){env=json!({});}env.as_object_mut().unwrap().remove("RUSTC");env.as_object_mut().unwrap().remove("RUSTUP_TOOLCHAIN");assert_eq!(c["environment"],env);commands+=1;}assert_eq!(read(format!("{R}/{dir}/result.json"))["status"],"complete");assert_eq!(read(format!("{R}/{dir}/completed.json")),json!(names));}
assert_eq!(commands,8);for(p,h)in&pins{assert_eq!(hash(p),*h,"pin {p}");}let tests=fs::read_to_string(format!("{R}/native/observer-tests/stdout.log")).unwrap();assert!(tests.contains("2 passed; 0 failed; 0 ignored; 0 measured; 125 filtered out"));assert_eq!(read(format!("{R}/native/observer-tests/tests.json"))["passed_tests"].as_array().unwrap().len(),2);let link=read(format!("{R}/link-runs/link-driver/command.json"));for s in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(link["argv"].as_array().unwrap().contains(&json!(s)));}
let manifest=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let edits=read(format!("{R}/observer-edits.json"));let mut exact=0;for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(p)),h.as_str().unwrap());let mut bytes=fs::read(Path::new(R).join("source").join(p)).unwrap();if format!("{:x}",Sha256::digest(&bytes))==h.as_str().unwrap(){exact+=1;}if p=="crates/zopro-core/src/lib.rs"{let suffix=edits["lib_suffix"].as_str().unwrap();assert!(bytes.ends_with(suffix.as_bytes()));bytes.truncate(bytes.len()-suffix.len());}let selected=edits["replacements"].as_array().unwrap().iter().filter(|e|e["path"]==*p).collect::<Vec<_>>();if !selected.is_empty(){let mut text=String::from_utf8(bytes).unwrap();for e in selected.into_iter().rev(){let new=e["new"].as_str().unwrap();assert_eq!(text.matches(new).count(),1);text=text.replace(new,e["old"].as_str().unwrap());}bytes=text.into_bytes();}assert_eq!(format!("{:x}",Sha256::digest(bytes)),h.as_str().unwrap());if p.starts_with("crates/zopro-bn254/"){assert_eq!(hash(Path::new(R).join("source").join(p)),h.as_str().unwrap());}}assert_eq!(exact,172);assert_eq!(fs::read(format!("{R}/locality.rs")).unwrap(),fs::read(format!("{R}/source/crates/zopro-core/src/pack_locality.rs")).unwrap());
let a=read(format!("{R}/analysis.json"));let jobs=read(format!("{R}/jobs.json"));assert_eq!(jobs.as_array().unwrap().len(),4);let mut reconstructed=BTreeMap::new();let mut all_groups=0u64;let mut all_pairs=0u64;let mut private_bytes=0;
for job in jobs.as_array().unwrap(){let name=job["name"].as_str().unwrap();let raw_path=job["private_trace"].as_str().unwrap();let raw=read(raw_path);let lines=fs::read_to_string(format!("{R}/runs/{name}/stdout.log")).unwrap();let matches=lines.lines().filter_map(|l|l.strip_prefix("LOCALITY ")).collect::<Vec<_>>();assert_eq!(matches.len(),1);let summary:Value=serde_json::from_str(matches[0]).unwrap();assert_eq!(a["cases"][name],summary);assert_eq!(hash(raw_path),summary["private_transcript_sha256"]);assert_eq!(summary["private_transcript_bytes"],fs::metadata(raw_path).unwrap().len());private_bytes+=fs::metadata(raw_path).unwrap().len();let oracle=read(job["fixture"]["oracle"].as_str().unwrap());assert_eq!(hash(job["fixture"]["fixture"].as_str().unwrap()),oracle["fixture_sha256"]);assert_eq!(oracle["fixture_sha256"],raw["fixture_sha256"]);assert_eq!(summary["result_sha256"],oracle["expected_canonical_result_sha256"]);assert_eq!(oracle["independent_Arkworks_complete_MSM"],true);for k in["point_inputs_unchanged","independent_complete_MSM_hash_matches","no_latency_measurement"]{assert_eq!(summary[k],true);}assert_eq!(summary["workers"],job["workers"]);let workers=job["workers"].as_u64().unwrap();let mut tids=BTreeSet::new();let mut cpus=BTreeSet::new();for(w,v)in summary["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(v["worker"],w);assert_eq!(v["cpu"],if workers==1{2}else{w});assert!(tids.insert(v["tid"].as_u64().unwrap()));assert!(cpus.insert(v["cpu"].as_u64().unwrap()));}assert_eq!(tids.len()as u64,workers);
let mut keys=BTreeSet::new();let mut total=BTreeMap::<String,u64>::new();let mut hist=[0u64;9];let rows=raw["rows"].as_array().unwrap();assert_eq!(rows.len(),22);for(row,observed)in rows.iter().zip(summary["rows"].as_array().unwrap()){for k in["window","root_points","start","end"]{assert_eq!(row[k],observed[k]);}let n=row["root_points"].as_u64().unwrap();assert_eq!(n,if job["shape"]=="1x2"{30089}else{28852});let start=row["start"].as_u64().unwrap();let end=row["end"].as_u64().unwrap();let half=n.div_ceil(2);assert!(start==0||start==half);assert_eq!(end,(start+half).min(n));assert!(keys.insert((row["window"].as_u64().unwrap(),start,end)));for phase in 0..2{let mut counts=BTreeMap::<String,u64>::new();for k in["batches","pairs","full_groups","scalar_tail_pairs","aligned_consecutive","unaligned_consecutive","single_block_permutation","general_gather","consecutive_edges","possible_edges","unique_source_ordinals"]{counts.insert(k.into(),0);}let mut seen=BTreeSet::new();let mut blocks_hist=[0u64;9];let batches=row["batches"][phase].as_array().unwrap();counts.insert("batches".into(),batches.len()as u64);for batch in batches{let ids=batch.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();for &i in&ids{assert!(i>=start&&i<end);assert!(seen.insert(i));}*counts.get_mut("pairs").unwrap()+=ids.len()as u64;*counts.get_mut("scalar_tail_pairs").unwrap()+=(ids.len()%8)as u64;let mut pos=0;while pos+8<=ids.len(){let g=&ids[pos..pos+8];let tiles=g.iter().map(|i|i/8).collect::<BTreeSet<_>>();blocks_hist[tiles.len()]+=1;let ordered=(0..8).all(|j|g[j]==g[0]+j as u64);let k=if ordered&&g[0]%8==0{"aligned_consecutive"}else if ordered{"unaligned_consecutive"}else if tiles.len()==1{"single_block_permutation"}else{"general_gather"};*counts.get_mut(k).unwrap()+=1;*counts.get_mut("full_groups").unwrap()+=1;for j in 1..8{*counts.get_mut("consecutive_edges").unwrap()+=u64::from(g[j]==g[j-1]+1);}pos+=8;}}
counts.insert("unique_source_ordinals".into(),seen.len()as u64);counts.insert("possible_edges".into(),7*counts["full_groups"]);assert_eq!(counts["pairs"],8*counts["full_groups"]+counts["scalar_tail_pairs"]);assert!(counts["pairs"]<=end-start);let want=&observed["components"][phase];for(k,v)in&counts{assert_eq!(want[k],*v,"{name}:{k}");*total.entry(k.clone()).or_default()+=v;}assert_eq!(want["distinct_source_blocks_histogram"],json!(blocks_hist));for i in 0..9{hist[i]+=blocks_hist[i];}}}
let target=&a["totals"][name];assert_eq!(target["counts"],json!(total));assert_eq!(target["distinct_source_blocks_histogram"],json!(hist));let groups=total["full_groups"];for(key,count)in[("aligned_direct_group_fraction",total["aligned_consecutive"]),("all_consecutive_group_fraction",total["aligned_consecutive"]+total["unaligned_consecutive"]),("single_block_group_fraction",hist[1]),("general_gather_group_fraction",total["general_gather"]) ]{let actual=count as f64/groups as f64;assert!((actual-target[key].as_f64().unwrap()).abs()<1e-14);}all_groups+=groups;all_pairs+=total["pairs"];reconstructed.insert(name.to_string(),json!({"counts":total,"histogram":hist,"private_transcript_sha256":hash(raw_path)}));}
for shape in["1x2","2x2"]{assert_eq!(reconstructed[&format!("{shape}-w1")],reconstructed[&format!("{shape}-w32")]);}let ledger="/home/ubuntu/src/zopro-perf-work/finalize-drain-bundle176/proof-sha256-after.json";assert_eq!(read(ledger).as_array().unwrap().len(),29953);assert_eq!(hash(manifest["native_binary"].as_str().unwrap()),manifest["native_binary_sha256"]);let out=json!({"review_passed":true,"independent_of_observer_and_classifier_code":true,"source_pins":pins.len(),"successful_workflow_commands":commands,"new_focused_tests":2,"inherited_core_tests_filtered":125,"production_originals_exact":176,"private_originals_exact":172,"all176recover":true,"all17field_sources_exact":true,"complete_query_processes":4,"reviewed_full_groups_all_four_runs":all_groups,"reviewed_affine_pairs_all_four_runs":all_pairs,"private_transcript_bytes_all_four_runs":private_bytes,"cross_worker_transcripts_exact":true,"cases":reconstructed,"new_proofs":0,"proof_ledger":29953,"proof_ledger_sha256":hash(ledger),"adopted":false,"goal_achieved":false});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Independent review PASS:{}pins/8commands/{}full8groups/{}pairs;4complete MSM oracles and worker identity; no speed claim",pins.len(),all_groups,all_pairs);}
